args.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?paternalGrandfather ?paternalGrandfatherLabel WHERE {
  dbr:Abd_al-Aziz_ibn_al-Walid dbp:father ?father .
  ?father dbp:father ?paternalGrandfather .
  OPTIONAL { ?paternalGrandfather rdfs:label ?paternalGrandfatherLabel . FILTER (lang(?paternalGrandfatherLabel) = "en") }
}

